# Verify the graph
edges = [
    (0,7), (0,8), (0,9),
    (1,7), (1,8), (1,10),
    (2,7), (2,9), (2,11),
    (3,8), (3,10), (3,12),
    (4,9), (4,11), (4,13),
    (5,10), (5,12), (5,14),
    (6,7)
]

n = 15
# Check vertex range
for u,v in edges:
    assert 0 <= u < v < n, f"Invalid edge {u},{v}"

# Check bipartite (2-colorable)
# Use BFS coloring
from collections import deque
adj = [[] for _ in range(n)]
for u,v in edges:
    adj[u].append(v)
    adj[v].append(u)

color = [-1]*n
def is_bipartite():
    for start in range(n):
        if color[start] == -1:
            color[start] = 0
            q = deque([start])
            while q:
                u = q.popleft()
                for v in adj[u]:
                    if color[v] == -1:
                        color[v] = 1 - color[u]
                        q.append(v)
                    elif color[v] == color[u]:
                        return False
    return True

print("Bipartite:", is_bipartite())

# Check girth >= 4 (no triangles)
def has_triangle():
    for u in range(n):
        for v in adj[u]:
            if v > u:
                for w in adj[v]:
                    if w > v and w in adj[u]:
                        return True
    return False

print("Has triangle:", has_triangle())

# Count edges
print("Number of edges:", len(edges))

# Check for 4-cycle (girth might be 4)
# We'll just confirm no 3-cycle.
print("Girth >= 4:", not has_triangle())
